export function findCatalogElement(idOrSymbolOrName: string): SubstanceDetail | undefined {
  const key = idOrSymbolOrName.trim().toLowerCase();
  return FULL_ELEMENTS_CATALOG.find(
    (e) =>
      e.id.toLowerCase() === key ||
      (e.symbol && e.symbol.toLowerCase() === key) ||
      e.name.toLowerCase() === key ||
      String(e.atomic_number) === key
  );
}

export function getCatalogReactionsForElement(idOrSymbolOrName: string): Reaction[] {
  const el = findCatalogElement(idOrSymbolOrName);
  if (!el || !el.symbol) return [];
  return ELEMENT_REACTIONS_CATALOG[el.symbol] || [];
}
